/// This API is useful for a temporary quorum loss situation on your service.  Call the GetQuorumLossProgress API with the same OperationId to return information on the operation started with this API.  This can only be called on stateful persisted (HasPersistedState==true) services.  Do not use this API on stateless services or stateful in-memory only services.
pub async fn start_quorum_loss(
    configuration: &configuration::Configuration,
    api_version: &str,
    service_id: &str,
    partition_id: &str,
    operation_id: &str,
    quorum_loss_mode: &str,
    quorum_loss_duration: i32,
    timeout: Option<i64>,
) -> Result<reqwest::StatusCode, Error<StartQuorumLossError>> {
    // add a prefix to parameters to efficiently prevent name collisions
    let p_query_api_version = api_version;
    let p_path_service_id = service_id;
    let p_path_partition_id = partition_id;
    let p_query_operation_id = operation_id;
    let p_query_quorum_loss_mode = quorum_loss_mode;
    let p_query_quorum_loss_duration = quorum_loss_duration;
    let p_query_timeout = timeout;

    let uri_str = format!(
        "{}/Faults/Services/{serviceId}/$/GetPartitions/{partitionId}/$/StartQuorumLoss",
        configuration.base_path,
        serviceId = crate::apis::urlencode(p_path_service_id),
        partitionId = crate::apis::urlencode(p_path_partition_id)
    );
    let mut req_builder = configuration
        .client
        .request(reqwest::Method::POST, &uri_str);

    req_builder = req_builder.query(&[("api-version", &p_query_api_version.to_string())]);
    req_builder = req_builder.query(&[("OperationId", &p_query_operation_id.to_string())]);
    req_builder = req_builder.query(&[("QuorumLossMode", &p_query_quorum_loss_mode.to_string())]);
    req_builder = req_builder.query(&[(
        "QuorumLossDuration",
        &p_query_quorum_loss_duration.to_string(),
    )]);
    if let Some(ref param_value) = p_query_timeout {
        req_builder = req_builder.query(&[("timeout", &param_value.to_string())]);
    }
    if let Some(ref user_agent) = configuration.user_agent {
        req_builder = req_builder.header(reqwest::header::USER_AGENT, user_agent.clone());
    }

    let req = req_builder.build()?;
    let resp = configuration.client.execute(req).await?;

    let status = resp.status();

    if status.is_success() {
        Ok(status)
    } else {
        let content = resp.text().await?;
        let entity: Option<StartQuorumLossError> = serde_json::from_str(&content).ok();
        Err(Error::ResponseError(ResponseContent {
            status,
            content,
            entity,
        }))
    }
}
